//! Vectors for the instantiable components, generated by
//! `scripts/cpp_vectors/components_vectors.cpp`.

use std::collections::HashMap;

use fp_core::code::code::Code;
use fp_core::field::ext::{F, E};
use fp_core::iop::bat::{combine, combine_rows};
use fp_core::iop::batt::{batt_claim, batt_row};
use fp_core::iop::laid::{
    laid_block_ok, laid_form, laid_ok, IndexWeights, LaidBlock, LaidMatrix,
};
use fp_core::iop::mask::{receipt_for_a_test, MaskLedger, SendAccess};
use fp_core::iop::psc::{KeptTerm, PscOutput};
use fp_core::iop::relation::{
    group_index, Codes, GroupLayout, OracleShape, Part, Row, Statement,
};
use fp_core::iop::send_pad::send_pad;
use fp_core::iop::tensor::{Form, Tensor};
use fp_core::chain::public::PublicBytes;

const VECTORS: &str = include_str!("../../fixtures/components_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn f(s: &str) -> F {
    F(u64::from_str_radix(s, 16).unwrap())
}

fn e(s: &str) -> E {
    let p: Vec<&str> = s.trim_start_matches('=').split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([f(p[0]), f(p[1]), f(p[2])])
}

fn eseq(s: &str) -> Vec<E> {
    s.trim_start_matches('=')
        .split(';')
        .filter(|x| !x.is_empty())
        .map(e)
        .collect()
}

fn ev_of(rest: &str, key: &str) -> E {
    e(rest.split(key).nth(1).unwrap().split_whitespace().next().unwrap())
}

#[test]
fn component_vectors_match_the_cpp_reference() {
    let text = VECTORS;
    let mut lines = text.lines();
    let mut count = 0usize;

    // ---- the mask ledger ----
    let mut ledger = MaskLedger::new(receipt_for_a_test(3, 1, 12, 3, 2));
    assert_eq!(lines.next().unwrap(), "LEDGER oracle=3 first=1 count=12 rows=3 log_rows=2");
    for j in 0..12 {
        let line = lines.next().unwrap();
        let kv = fields(line);
        let s = ledger.take();
        assert_eq!(s.oracle(), kv["oracle"].parse::<u32>().unwrap());
        assert_eq!(s.index(), kv["index"].parse::<u32>().unwrap());
        assert_eq!(ledger.left(), kv["left"].parse::<u32>().unwrap());
        assert!(line.contains(&format!("j={}", j)));
        count += 1;
    }
    ledger.close();
    assert_eq!(lines.next().unwrap(), "CLOSED left=0");

    // ---- the group layout ----
    let mut codes = Codes::default();
    codes.base.push(Code { log_n: 3, ell: 2, r: 1 });
    codes.mask.push(Code { log_n: 2, ell: 2, r: 1 });
    let mut s = Statement::new(codes);
    let mut shape = OracleShape::default();
    shape.name = "a".into();
    shape.code = 0;
    shape.main_rows = 2;
    shape.main_deg = 1;
    shape.mask_rows = 2;
    shape.mask_code = 0;
    shape.answers = 1;
    let sampled = |s: &mut Statement, shape: OracleShape| {
        let o = s.sent(shape);
        let pad = Vec::new();
        s.sampled(
            &SendAccess,
            o,
            vec![Row::default()],
            pad,
            receipt_for_a_test(o, 0, 4, 1, 0),
        );
        o
    };
    let oa = sampled(&mut s, shape.clone());
    let mut bshape = shape.clone();
    bshape.name = "b".into();
    bshape.main_rows = 4;
    let ob = sampled(&mut s, bshape);
    let mut cshape = shape;
    cshape.name = "c".into();
    cshape.main_rows = 1;
    let oc = sampled(&mut s, cshape);
    let g = s.new_group("g", 0, 0);
    s.join(g, oa, false);
    s.join(g, ob, false);
    s.join(g, oc, true);
    let l = s.layout(g);
    let line = lines.next().unwrap();
    assert!(line.starts_with("LAYOUT"));
    let kv = fields(line);
    assert_eq!(l.members, vec![oa, ob, oc]);
    assert_eq!(l.kept, vec![false, false, true]);
    assert_eq!(l.k, kv["k"].parse::<u32>().unwrap());
    assert_eq!(l.h, kv["h"].parse::<u32>().unwrap());
    assert_eq!(l.log_ell, kv["log_ell"].parse::<u32>().unwrap());
    assert_eq!(l.log_ell_zk, kv["log_ell_zk"].parse::<u32>().unwrap());
    let line = lines.next().unwrap();
    let mf: Vec<u64> = line["MAIN_FIRST".len()..].split_whitespace().map(|x| x.parse().unwrap()).collect();
    assert_eq!(l.main_first, mf);
    let line = lines.next().unwrap();
    let zf: Vec<u64> = line["MASK_FIRST".len()..].split_whitespace().map(|x| x.parse().unwrap()).collect();
    assert_eq!(l.mask_first, zf);
    let line = lines.next().unwrap();
    let gi: Vec<u64> = line["GROUP_INDEX".len()..].split_whitespace().map(|x| x.parse().unwrap()).collect();
    for (i, want) in gi.iter().enumerate() {
        assert_eq!(group_index(i as u64, 1, 0, 2), *want);
    }

    // BAT's carry of a term, unit, run and form.
    {
        let mut row = Row::plain("carry");
        row.add(oa, Part::Main, Tensor::product(&[F(3), F(5)], 2, e("7,8,9")));
        row.add_unit(oa, Part::Main, 1, e("b,c,d"));
        row.add_run(oa, Part::Mask, 0, 2, vec![e("d,e,f"), e("11,12,13")]);
        let mut form = Form::default();
        form.add_entry(2, e("13,14,15"));
        row.add_form(oa, form);
        row.target = e("17,18,19");
        s.add_row(g, row);
        let input = s.begin_run(g);
        let out = combine(&s, g, input, e("1d,1e,1f"));
        let line = lines.next().unwrap();
        assert!(line.starts_with("BAT_CARRY"));
        let target = ev_of(&line, "target=v=");
        assert_eq!(out.target, target);
        let dpart = line.split(" d=").nth(1).unwrap().split(" kept=").next().unwrap();
        assert_eq!(out.d, eseq(dpart));
        let cpart = line.split(" c=").nth(1).unwrap();
        let cvals: Vec<u64> = cpart.split(',').map(|x| u64::from_str_radix(x, 16).unwrap()).collect();
        for (j, want) in cvals.iter().enumerate() {
            assert_eq!(out.c.at(j as u64).0[0].0, *want, "carry c[{}]", j);
        }
        assert!(line.contains("kept=0"));
        count += 1;
    }

    // BAT's pure row batching.
    {
        let mut a = Row::plain("a");
        a.add_unit(0, Part::Main, 2, e("1f,20,21"));
        a.target = e("25,26,27");
        let mut b = Row::plain("b");
        b.add_unit(1, Part::Mask, 0, e("29,2a,2b"));
        b.add_run(1, Part::Mask, 1, 1, vec![e("2b,2c,2d"), e("2f,30,31")]);
        b.target = e("35,36,37");
        let out = combine_rows(&[a, b], e("3b,3c,3d"), "batched");
        let line = lines.next().unwrap();
        assert_eq!(out.target, ev_of(line, "target=v="));
        assert_eq!(out.units.len(), 2);
        assert_eq!(out.runs.len(), 1);
        for j in 0..4u64 {
            let line = lines.next().unwrap();
            assert_eq!(out.coefficient(0, Part::Main, j), ev_of(&line, "v="));
        }
        count += 1;
    }

    // BATT's claim and output row.
    {
        let mut rows = Vec::new();
        for j in 0..2u64 {
            let mut r = fp_core::iop::batt::tensor_row(
                vec![Tensor::product(
                    &[F(80 + j), F(90 + j)],
                    2,
                    e(&format!("{:x},{:x},{:x}", 100 + j, 101 + j, 102 + j)),
                )],
                vec![
                    e(&format!("{:x},{:x},{:x}", 110 + j, 111 + j, 112 + j)),
                    e(&format!("{:x},{:x},{:x}", 120 + j, 121 + j, 122 + j)),
                ],
                e(&format!("{:x},{:x},{:x}", 130 + j, 131 + j, 132 + j)),
            );
            r.masks.clear();
            rows.push(r);
        }
        let b = batt_claim(&mut rows, e("7,8,9"));
        let line = lines.next().unwrap();
        assert!(line.starts_with("BATT"));
        let chipart = line.split("chi=").nth(1).unwrap().split(" target=").next().unwrap();
        assert_eq!(b.chi, eseq(chipart));
        assert_eq!(b.claim.target, ev_of(line, "target=v="));
        let gamma = vec![e("8c,8d,8e"), e("96,97,98")];
        let a = (b.summand.at)(&gamma, &[]);
        let atpart = line.split(" AT ").nth(1).unwrap();
        let avals: Vec<E> = atpart.split_whitespace().map(e).collect();
        assert_eq!(a, avals);
        let out = PscOutput {
            point: gamma,
            row_masks: Vec::new(),
            row_maps: vec![KeptTerm { map: 0, coeff: e("a0,a1,a2") }],
            row_target: e("aa,ab,ac"),
            ends: Vec::new(),
        };
        let r = batt_row(&rows, out);
        let line = lines.next().unwrap();
        assert_eq!(r.target, ev_of(line, "target=v="));
        let psipart = line.split(" psi=").nth(1).unwrap().split(" g=").next().unwrap();
        assert_eq!(r.psi, eseq(psipart));
        for j in 0..8u64 {
            let line = lines.next().unwrap();
            assert_eq!(r.g[0].at(j).0[0].0, u64::from_str_radix(&line.split("v=").nth(1).unwrap()[..16], 16).unwrap());
        }
        count += 1;
    }

    // The matrix layout's tensors.
    {
        let row_bits = 2;
        let place_bits = 2;
        let m = LaidMatrix {
            size_i: 2,
            size_c: 2,
            blocks: vec![LaidBlock {
                first_i: 0,
                first_c: 0,
                first_row: 0,
                first_place: 0,
                bits_i: 1,
                bits_c: 1,
                row_bits: 1,
                place_bits: 1,
                i_is_low: true,
            }],
        };
        let line = lines.next().unwrap();
        assert!(line.contains("LAID ok=1 fault=0"));
        assert!(laid_ok(&[m.clone()], row_bits, place_bits));
        assert!(m.blocks[0].public_fault().is_none());
        let on_i = IndexWeights::eq(&[e("c8,c9,ca")]);
        let on_c = IndexWeights::eq(&[e("d2,d3,d4")]);
        let form = laid_form(&m.blocks, row_bits, place_bits, &on_i, &on_c, e("dc,dd,de"));
        let line = lines.next().unwrap();
        assert!(line.contains("LAID_FORM n=1"));
        let vals: Vec<u64> = line.split('|').skip(1).flat_map(|s| s.split_whitespace()).map(|x| u64::from_str_radix(x, 16).unwrap()).collect();
        for (j, want) in vals.iter().enumerate() {
            assert_eq!(form.at(j as u64).0[0].0, *want, "laid form at {}", j);
        }
        let line = lines.next().unwrap();
        assert!(line.contains("LAID_BAD fault=1 in_table=0"));
        let bad = LaidBlock { first_i: 1, ..m.blocks[0] };
        assert!(bad.public_fault().is_some());
        assert!(!laid_block_ok(&bad, row_bits, place_bits));
        count += 1;
    }

    // The pad's places.
    {
        let mut codes = Codes::default();
        codes.base.push(Code { log_n: 4, ell: 4, r: 2 });
        codes.mask.push(Code { log_n: 3, ell: 4, r: 2 });
        let mut shape = OracleShape::default();
        shape.name = "pad".into();
        shape.code = 0;
        shape.main_rows = 2;
        shape.mask_rows = 2;
        shape.mask_code = 0;
        shape.answers = 2;
        let places = send_pad(&codes, &shape);
        let line = lines.next().unwrap();
        let want: Vec<u64> = line["PAD".len()..].split_whitespace().map(|x| x.parse().unwrap()).collect();
        assert_eq!(places.iter().map(|p| p.index).collect::<Vec<_>>(), want);
        assert_eq!(places[0].part, Part::Mask);
        count += 1;
    }

    assert!(count > 0 && lines.next().is_none());
}
